responses.text:
{
  "instrument": "§ 356a BGB",
  "jurisdiction": "DE",
  "summary": "Bieten Sie ab dem 19. Juni 2026 eine gut sichtbare Widerrufsfunktion mit Bestätigungsschritt an und bestätigen Sie jeden Widerruf unverzüglich auf einem dauerhaften Datenträger. § 356a BGB gilt für Unternehmer bei im elektronischen Geschäftsverkehr geschlossenen Verbraucherverträgen.",
  "effective_dates": [
    "2026-06-19"
  ],
  "obligations": [
    {
      "text": "Stellen Sie sicher, dass Verbraucher das Widerrufsrecht über eine Widerrufsfunktion ausüben können.",
      "quote": "hat der Unternehmer sicherzustellen, dass der Verbraucher das Widerrufsrecht auch durch eine Widerrufsfunktion ausüben kann"
    },
    {
      "text": "Kennzeichnen Sie die Widerrufsfunktion gut lesbar mit „Vertrag hier widerrufen“.",
      "quote": "Die Widerrufsfunktion ist mit den Worten „Vertrag hier widerrufen\" oder mit einer entsprechenden eindeutigen Formulierung in gut lesbarer Form zu kennzeichnen."
    },
    {
      "text": "Ermöglichen Sie das Absenden der Widerrufserklärung über eine Bestätigungsfunktion.",
      "quote": "hat der Unternehmer dem Verbraucher zu ermöglichen, die Widerrufserklärung über eine Bestätigungsfunktion abzusenden."
    },
    {
      "text": "Bestätigen Sie den Eingang des Widerrufs unverzüglich auf einem dauerhaften Datenträger.",
      "quote": "hat der Unternehmer dem Verbraucher unverzüglich auf einem dauerhaften Datenträger den Eingang der Widerrufserklärung zu bestätigen"
    }
  ]
}
